#define R iResolution.xy
#define A(U) texture(iChannel0,(U)/R)
#define B(U) texture(iChannel1,(U)/R)
#define Main void mainImage(out vec4 Q, in vec2 U)
vec4 hash(vec4 p4)
{
    p4 = fract(p4  * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}

Main {

    Q = A(U);
    vec4 n = A(U+vec2(0,1));
    vec4 e = A(U+vec2(1,0));
    vec4 s = A(U-vec2(0,1));
    vec4 w = A(U-vec2(1,0));
    Q.zw = -0.5*vec2(e.x-w.x,n.x-s.x);

    if (iMouse.z>0.) {
        vec2 m = iMouse.xy;
        if (m.x < .1*R.x) {
            Q.y = m.y/R.y;
        } else {
            vec2 u = U-m.xy;
            Q.x += .5*sign(Q.y-.5)*exp(-.01*exp(-4.*abs(Q.y*2.-1.))*dot(u,u));
            m.x = R.x-m.x;
            u = U-m.xy;
            Q.x += .5*sign(Q.y-.5)*exp(-.01*exp(-4.*abs(Q.y*2.-1.))*dot(u,u));
        }
    }
}

Main {
     vec3 light = R.xyy*vec3(1,1,2);
     vec4 a = A(U);
     Q = B(U)*.95;
     vec3 p = vec3(U,a.x);
     vec3 d = normalize(light-p);
     d = normalize(d+.005*(hash(vec4(U,iTime,iFrame)).xyz*2.-1.));
     p += d;
     for (float i = 0.; i < 100.; i++) {
         float l = length(p-light)-10.;
         float h = p.z-A(p.xy).x;
         p += d*min(h,l);


     }
     Q += dot(d,normalize(vec3(a.zw,1)))*exp(-.01*length(p-light));


    if (U.x < .1*R.x) {
        Q *= smoothstep(10.,12.,abs(a.y*R.y-U.y));
    }
}
